(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["si"] = {"ui":{"skip":"අන්තර්ගතයට පිවිසෙන්න","back":"← AI-gile වෙත ආපසු","lang.button":"භාෂාව: {name}","lang.dialog":"භාෂාවක් තෝරන්න","lang.search":"භාෂා සොයන්න","lang.none":"ගැළපෙන භාෂාවක් නැහැ","lang.notYet":"{name} තවම පරිවර්තනය කර නැහැ","theme.aria":"ආලෝක සහ අඳුරු තේමා අතර මාරු වන්න","theme.toLight":"ආලෝක තේමාවට මාරු වන්න","theme.toDark":"අඳුරු තේමාවට මාරු වන්න","index.title":"AI-gile: ඔබේ AI සංවර්ධන කණ්ඩායම, එකම පුවරුවක","index.description":"AI-gile යනු AI කේත කණ්ඩායම් සඳහා kanban පුවරුවකි. ඔවුන් ඔබ නිදාගන්නා විට වැඩ කරයි; ඔබට තීරණය කිරීමට, පරීක්ෂා කිරීමට සහ පිළිගැනීමට කෙටි ගොඩක් ලැබේ.","hero.logoAlt":"AI-gile පුවරුවේ අයිකනය","hero.h1.html":"ඔබේ AI සංවර්ධන කණ්ඩායම, එකම&nbsp;පුවරුවක.","hero.alpha":"🐣 වසා තැබූ pre-alpha","hero.alphaTitle":"මුල් අවධියේ, නොසම්පූර්ණයි: උත්සාහ කරන්නට ස්තූතියි!","hero.lede":"ඔබ නිදාගන්නා විට ඔවුන් ගොඩනඟයි. ඔබ අවදි වන්නේ කෙටි ගොඩකට: ප්‍රශ්න කිහිපයක්, පරීක්ෂා කළ යුතු දේ කිහිපයක්, දම් දියමන්ති එකක් දෙකක්. ක්ලික් කරන්න, පිළිගන්න, නැවත ඔබේ කෝපි කෝප්පයට.","dl.windows":"Windows යෙදුම","dl.browser":"ඔබේ බ්‍රවුසරයේ ධාවනය කරන්න","dl.soon":"ඉක්මනින්","dl.notify":"🔔 විවෘත වූ විට මට කියන්න","dl.notifySmall":"Alpha හෝ beta","hero.secondary":"Agile, නමුත් කණ්ඩායමට කවදාවත් stand-up කෝපි අවශ්‍ය නැහැ. (ඔවුන් stand-up කරනවා ඒත්.)","pitch.h2":"AI-gile ඔබට අවශ්‍ය වචන ගණනින්","pitch.lede":"දිගක් තෝරන්න, වචනයක සිට 144 දක්වා. හැම දිගක්ම ඒ ප්‍රමාණයට ලියූ වෙනම විස්තරයකි. ස්ලයිඩරය ඇදන්න හෝ ඊතල යතුරු භාවිතා කරන්න.","pitch.rangeLabel":"වචනවලින් දිග","pitch.dice":"🎲 තවත් අනුවාදයක්","pitch.words.one":"වචන {n}ක්","pitch.words.other":"වචන {n}ක්","pitch.letters.one":"අකුරු {n}ක්","pitch.letters.other":"අකුරු {n}ක්","pitch.chars.one":"අක්ෂර {n}ක්","pitch.chars.other":"අක්ෂර {n}ක්","count.line.html.one":"දැන් පුවරුවේ කාඩ්පත් {n}ක් ඇත","count.line.html.other":"දැන් පුවරුවේ කාඩ්පත් {n}ක් ඇත","features.aria":"එය කරන දේ","f.pile.h":"ඔබට ඇති එකම ගොඩ","f.pile.html":"<b>ඔබට</b> තුළ සියලු ව්‍යාපෘති හරහා ඔබ එනතුරු බලා සිටින සියල්ල ඇත: ප්‍රශ්න, පරීක්ෂා කළ යුතු දේ, මිනිසෙකුට පමණක් කළ හැකි කාර්ය. ඔබේ පෝලිම කියන්නේ ඊළඟට මොනවාද සහ කොපමණ කාලයක් යනවාද කියායි.","f.sleep.h":"ඔබ නිදාගන්නා විට වැඩ කරන කණ්ඩායම්","f.sleep.p":"හැම ව්‍යාපෘතියකටම ලීඩ් කෙනෙක් සහ AI ඒජන්ට්වරුන්ගේ කණ්ඩායමක් ඇත. කාඩ්පතක් මත අදහසක් දමන්න; කණ්ඩායම අවදි වී වැඩ කර, මහන්සි වූ මිනිසෙකුට අනුගමනය කළ හැකි පියවර සමඟ ආපසු දෙයි.","f.tester.h":"පළමුව AI පරීක්ෂකයා පරීක්ෂා කරයි","f.tester.p":"කිසිවක් ඔබ වෙත පැමිණීමට පෙර, පරීක්ෂකයා යෙදුමේ පිටපතක පියවර අනුගමනය කර, තිරපිටපතක් සමඟ තමා දුටු දේ පෙන්වයි. සමත් වූ ඒවා පෙරළා බලා එක් ක්ලික් එකකින් පිළිගන්න.","f.proof.h":"සාක්ෂි, පොරොන්දු නොවේ","f.proof.p":"හැම භාරදීමකම වෙනස් වූ දේ පෙන්වයි: ගොනු, වෙනස්කම්, තිරපිටපත්. ඒක ඉවරද කියා බලන්න හැම යෙදුමක්ම විවෘත කළ යුතු නැහැ.","f.chat.h":"ඔබේ ලීඩ්වරුන් සමඟ කතා කරන්න","f.chat.p":"Discord වැනි තීරුවක්: ව්‍යාපෘතියකට අයිකනයක්, ඔබට අවශ්‍ය දේට දම් දියමන්ති. ලීඩ් කෙනෙකුට අදහසක් යවන්න; ඔහු එය කාඩ්පත් සහ සැලැස්මක් බවට හරවයි, ✅ යන්න බොත්තමක් සමඟ.","f.tidy.h":"තමන්ම පිළිවෙළට තබාගනී","f.tidy.p":"සම්බන්ධ කාඩ්පත් එකට ගැලපේ, අවුල් සිරස්තල නිවැරදි වේ, ටෝකන පරීක්ෂාවක් කේතය සැහැල්ලුවෙන් තබයි. මාරු වීමට අඩු දේ, සිතීමට අඩු දේ.","f.private.h":"ඔබේම, ඔබේ පරිගණකයේ","f.private.li1":"පුවරුව ඔබේම යන්ත්‍රයේ ක්‍රියා කරන අතර පිළිතුරු දෙන්නේ ඔබට පමණි.","f.private.li2":"මිනිසුන් අතර පෞද්ගලික පණිවිඩ end-to-end සංකේතනය කර ඇත.","f.private.li3":"ගිණුම් නැහැ, ට්‍රැකර් නැහැ, cookies නැහැ.","f.lang.h":"ඔබේ භාෂාවෙන්","f.lang.p":"ලන්දේසි, වෙල්ෂ් සහ ජපන් සිට මුහුදු කොල්ලකරුවන්, Yoda සහ Klingon දක්වා භාෂා 120කට වැඩි, සංවර්ධක වචන සඳහා ඉංග්‍රීසියට ඉක්මන් මාරුවක් සමඟ.","tl.aria":"පළමු සංවාදයේ සිට සැලැස්ම දක්වා කාලරේඛාව","tl.h2":"පළමු කතාබහේ සිට ඊළඟට එන දේ දක්වා","tl.lede":"සැබෑ දින සහ වේලාවන්, ඔබේම වේලා කලාපයෙන්. අදින් පසු එය සැලැස්මකි, පොරොන්දු වූ දින නැහැ.","tl.today":"අද","tl.planned":"සැලසුම් කළ","tl.cards.one":"කාඩ්පත් {n}ක්","tl.cards.other":"කාඩ්පත් {n}ක්","join.h2":"එක් වන්න","join.lede":"AI-gile ගොඩනඟන්නේ කුඩා මිනිසෙක් සහ ඉවසිලිවන්ත ඒජන්ට්වරු රාශියක්. දැනට එය පෞද්ගලිකයි, මිතුරන් සමඟ වසා තැබූ alpha එකක. විවෘත වූ විට උත්සාහ කරන්න ඕනද?","join.btn":"උනන්දුව ලියාපදිංචි කරන්න","join.small":"අපි ඔබට ඊමේල් කරනවා, වෙන කිසිවක් නැහැ","footer.tag":"AI-gile. ට්‍රැකර් නැහැ, cookies නැහැ, stand-up කෝපි නැහැ.","footer.licence":"ව්‍යාපාරික බලපත්‍රය","footer.status":"තත්ත්වය","form.sending":"යවමින්…","form.failed":"එය සාර්ථක වුණේ නැහැ: පසුව නැවත උත්සාහ කරන්න.","form.offline":"AI-gile වෙත ළඟා විය නොහැකි විය: පසුව නැවත උත්සාහ කරන්න.","interest.title":"AI-gile: alpha විවෘත වූ විට මට කියන්න","interest.description":"AI-gile හි වසා තැබූ alpha හෝ beta විවෘත වූ විට දැනගැනීමට ඔබේ ඊමේල් එක තබන්න.","interest.h1":"🔔 විවෘත වූ විට මට කියන්න","interest.lede":"AI-gile වසා තැබූ pre-alpha එකක ඇත. ඔබේ ඊමේල් එක තබන්න, ඔබට ඉඩක් ඇති වූ විට අපි එක් වරක් ලියන්නෙමු.","interest.email":"ඔබේ ඊමේල්","interest.which":"කුමන පරීක්ෂණය?","interest.alpha":"වසා තැබූ alpha: මුල්, රළු, වෙනස්කම් රාශියක්","interest.beta":"Beta: වඩා ස්ථාවර, පසුව","interest.both":"ඕනෑම එකක්, පළමුව එන එක","interest.submit":"මාව ලැයිස්තුවට දමන්න","interest.thanks":"ස්තූතියි! ඔබ ලැයිස්තුවේ ඇත.","licence.title":"AI-gile: ව්‍යාපාරික බලපත්‍රය","licence.description":"ඔබේ ව්‍යාපාරයේ AI-gile භාවිතා කරනවාද? නොමිලේ ව්‍යාපාරික බලපත්‍රයක් සඳහා අයදුම් කරන්න.","licence.h1":"📜 ව්‍යාපාරික බලපත්‍රය","licence.lede":"වැඩට AI-gile භාවිතා කරනවාද? ඔබ කවුරුන්ද සහ ඔබ කරන්නේ මොකක්ද කියා අපට කියන්න. එයින් යම් යහපතක් වේ නම්, බලපත්‍රය නොමිලේයි.","licence.company":"සමාගම","licence.website":"වෙබ් අඩවිය","licence.what":"ඔබ කරන දේ","licence.how":"එය ලෝකයට උදව් වන ආකාරය","licence.email":"ඊමේල්","licence.submit":"අයදුම් කරන්න","licence.thanks":"ස්තූතියි! අපි ඊමේල් මගින් පිළිතුරු දෙන්නෙමු.","status.title":"AI-gile තත්ත්වය","status.h1":"AI-gile තත්ත්වය","status.quiet":"සියල්ල සන්සුන්","status.checking":"පරීක්ෂා කරමින්…","status.offline":"තත්ත්ව සේවාවට දැන් ළඟා විය නොහැක (නැවත උත්සාහ කරමින්)","status.updated":"යාවත්කාලීන කළේ {ago}","status.justNow":"මේ දැන්","status.min":"මිනිත්තු {n}කට පෙර","status.hours":"පැය {n}කට පෙර","status.days":"දින {n}කට පෙර","live.h2":"එය ගොඩනැගෙන හැටි සජීවීව බලන්න","live.caption":"සෑම කාඩ්පතක්ම සඟවා ඇත: ඔබ දකින්නේ වැඩේ හැඩය මිස වචන නොවේ.","live.watching.one":"සජීවී: {n} දෙනෙක් බලමින්","live.watching.other":"සජීවී: {n} දෙනෙක් බලමින්","live.offline":"සජීවී පුවරුව ටිකක් විවේක ගනිමින් සිටී. ඉක්මනින් නැවත බලන්න.","live.cols":"Backlog|කළ යුතු|කරමින්|කණ්ඩායම පරීක්ෂා කරමින්|ඔබට test කිරීමට|කණ්ඩායමට|අවසන්","live.last.now":"අන්තිම කාඩ්පත දැන් ම ගෙන ගියා","live.last.min.one":"අන්තිම කාඩ්පත විනාඩි {n}කට පෙර ගෙන ගියා","live.last.min.other":"අන්තිම කාඩ්පත විනාඩි {n}කට පෙර ගෙන ගියා","live.last.hour.one":"අන්තිම කාඩ්පත පැය {n}කට පෙර ගෙන ගියා","live.last.hour.other":"අන්තිම කාඩ්පත පැය {n}කට පෙර ගෙන ගියා","live.last.day.one":"අන්තිම කාඩ්පත දින {n}කට පෙර ගෙන ගියා","live.last.day.other":"අන්තිම කාඩ්පත දින {n}කට පෙර ගෙන ගියා"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","රොබෝවරු.","භාරදුන්නා."]},{"n":2,"texts":["රොබෝ kanban.","ඒජන්ට්වරු, පිළිවෙළට.","අදහස්, ගොඩනැගුණා."]},{"n":3,"texts":["රොබෝවරුන්ගේ kanban.","අදහස් විශේෂාංග වේ.","නොමිලේ ඒජන්ට් kanban."]},{"n":5,"texts":["ඒජන්ට්වරු ධාවනය කරන kanban පුවරුව.","ඔබ කාඩ් ලියන්න. ඒජන්ට්වරු ගොඩනඟති.","නොමිලේ, ප්‍රාදේශීය, පරීක්ෂිත, ටිකක් විහිළුයි."]},{"n":8,"texts":["AI ඒජන්ට්වරු වැඩ කරන නොමිලේ kanban පුවරුවක්.","අදහසක් ලියන්න. ඒජන්ට්වරු ගොඩනඟති. ඔබ පිළිගන්න.","එක් මිනිසෙකුට සහ ඉවසිලිවන්ත රොබෝවරුන්ට agile."]},{"n":13,"texts":["ඔබේ පරිගණකයේ ඇති kanban පුවරුවක, AI ඒජන්ට්වරු කාඩ්පත් ගෙන වැඩ කරති.","අදහසක් ලියන්න. ඒජන්ට් කණ්ඩායමක් ගොඩනඟයි. පරීක්ෂකයෙක් බලයි. ඔබ ඔව් කියයි.","නොමිලේ, ගිණුම් නැහැ, ට්‍රැකර් නැහැ: පුවරුවක්, රොබෝවරු කිහිප දෙනෙක් සහ පාලනය ඔබ."]},{"n":21,"texts":["AI-gile යනු කේත ලියන AI ඒජන්ට්වරුන් සමඟ වැඩ කිරීමට kanban පුවරුවකි. ඔවුන් කාඩ්පත් ගනී; ඔබ ඒවා පරීක්ෂා කර පිළිගනී.","හැම ව්‍යාපෘතියකටම ලීඩ් කෙනෙක් සහ AI ඒජන්ට්වරුන්ගේ කණ්ඩායමක් ලැබේ. ඕනෑම කාඩ්පතක් මත අදහසක් දමන්න, කණ්ඩායම වැඩට බසී.","ඔබේම පරිගණකයේ ක්‍රියා කරන නොමිලේ පුද්ගලික කාර්ය පුවරුවක්. කම්කරුවෝ රොබෝවරු ය. ඔව් කියන්නේ ඔබ පමණි. තීරණ ගන්නේත් ඔබයි, හැමවිටම."]},{"n":34,"texts":["ඔබ අදහස් පුවරුවේ තබයි. AI ඒජන්ට්වරුන්ගේ කණ්ඩායමක් ඒවා ක්‍රියාත්මක විශේෂාංග බවට හරවා, පරීක්ෂා කර, අත්හදා බැලීමට පියවර සමඟ ඔබට ආපසු දෙයි. ඔබ කියන තුරු කිසිවක් අවසන් ලෙස නොගණී.","AI-gile යනු Rich විසින් දැන් එය කළමනාකරණය කරන ඒජන්ට්වරුන්ගේ විශාල උදව්වෙන් ගොඩනැඟූ ගෙදර හදාගත් kanban පුවරුවකි. එය නොමිලේ, ඔබේ පරිගණකයේ ක්‍රියා කරයි, මිතුරන් සමඟ බෙදාගනී, විකුණන්නේ නැහැ.","Backlog සිට අවසන් දක්වා තීරු සහිත සාමාන්‍ය kanban පුවරුවක් සිතන්න, කාඩ්පත් ගන්නේ AI ඒජන්ට්වරු නම් පමණි. ඔවුන් ප්‍රගතිය වාර්තා කරයි, හිරවුණු විට අසයි, සැමවිටම ඔබේ අනුමැතිය බලා සිටියි."]},{"n":55,"texts":["AI-gile යනු කණ්ඩායම AI ඒජන්ට්වරුන්ගෙන් සමන්විත kanban පුවරුවකි. හැම ව්‍යාපෘතියකටම වැඩ සැලසුම් කරන ලීඩ් කෙනෙක් සහ ඒවා ගොඩනඟන උදව්කරුවන් ඇත. විශේෂාංගයක් සූදානම් වූ විට AI පරීක්ෂකයා එය අත්හදා බලා තිරපිටපතක් ගනී, ඉන්පසු එය ඔබේ ගොඩට පැමිණේ. පිළිගන්න, නැතහොත් අදහසක් දමන්න, ඔවුන් එය නැවත කරයි.","එය ආරම්භ වූයේ එකවර AI කේත සැසි රාශියක් නිරීක්ෂණය කිරීමට එක් අයෙකුගේ ක්‍රමයක් ලෙසයි, පසුව නියම පුවරුවක් බවට වැඩුණා. එය ඔබේ යන්ත්‍රයේ ක්‍රියා කරයි, ගිණුමක් අවශ්‍ය නැහැ, ට්‍රැකර් නැහැ. මිතුරන්ට සහ කුතුහලයෙන් සිටින අයට එය නොමිලේ. එය නොසම්පූර්ණ ද වන නිසා රළු තැන් සහ සමහර විට පුදුම දේවල් බලාපොරොත්තු වන්න.","මෙන්න අවංක අනුවාදය. අදහස් තවමත් ඔබට තිබිය යුතුයි, ප්‍රතිඵල තවමත් ඔබ පරීක්ෂා කළ යුතුයි. AI-gile ඒ අතර ඇති සියල්ල කරයි: කාඩ්පත් පිළිවෙළට තබයි, ඔබ අදහසක් දමන විට නිවැරදි ඒජන්ට් අවදි කරයි, වෙනස් වූ දේ හරියටම පෙන්වයි, සියල්ල ඔබට කෙටි ගොඩකට එක් කරයි. ඒ සියල්ල ඔබේම පරිගණකයේ, ගිණුමක් හෝ ට්‍රැකර් නැතිව."]},{"n":89,"texts":["AI-gile යනු ඔබේම පරිගණකයේ ධාවනය කරන නොමිලේ kanban පුවරුවකි. මිනිසුන් වෙනුවට හැම ව්‍යාපෘතියකටම AI ඒජන්ට්වරුන්ගේ කණ්ඩායමක් ඇත: ඔබේ අදහස් කාඩ්පත් සහ සැලැස්මක් බවට හරවන ලීඩ් කෙනෙක්, සහ ප්‍රමුඛතා අනුපිළිවෙලට කාඩ්පත් ගන්නා උදව්කරුවන්. යමක් ගොඩනැඟූ විට AI පරීක්ෂකයා පරීක්ෂණ පියවර අනුගමනය කර තමා දුටු දේ ඔබට පෙන්වයි. ඉන්පසු එය ඔබට යනුවෙන් නම් කළ ගොඩකට රැඳී සිටියි. ඔබ පිළිගනී, නැතහොත් අදහසක් දමයි, කණ්ඩායම නැවත උත්සාහ කරයි. ඔබ නැතිව කිසිවක් අවසන් වෙත නොයයි. ගිණුම් නැහැ, ට්‍රැකර් නැහැ, ඔබේම පරිගණකයේම ක්‍රියා කරයි.","ඔබ බලාපොරොත්තු නොවන කරුණු කිහිපයක්. රාත්‍රී මුරකරුවෙක් ඔබ නිදාගන්නා විට කළ යුතු තීරුව පුරවයි, ඔබෙන් පිළිතුරක් අවශ්‍ය නොවන කාඩ්පත් තෝරමින්. ටෝකන කවුන්ටරයක් ඒජන්ට්වරු අද සහ මේ සතියේ කොපමණ භාවිතා කළාදැයි පෙන්වයි, ටෝකන රහිත ප්‍රකාරය වියදම් නවත්වන්නැයි කියයි. ඔබට මිතුරන්ට පණිවිඩ යැවිය හැකි අතර පෞද්ගලික පණිවිඩ end-to-end සංකේතනය කර ඇත. පුවරුව භාෂා 120ක පමණ කතා කරයි, ලන්දේසි, ෆ්ලෙමිශ්, මුහුදු කොල්ලකරුවන් සහ Klingon ඇතුළව. ඒ කිසිවකට සත පහක්වත් ගාස්තු නැහැ, කිසිවෙක් ඔබට විකුණන්න උත්සාහ කරන්නේත් නැහැ.","AI-gile යනු කුඩා පුද්ගලික ව්‍යාපෘතියකි, සමාගමක් නොවේ. Rich ට අවශ්‍ය වූයේ හැම යෙදුමක්ම විවෘත නොකර AI කේත ව්‍යාපෘති කිහිපයක් බලා ගැනීමටයි, ඒ නිසා ඔහු සහ ඒජන්ට්වරු ඒ සඳහා පුවරුවක් ගොඩනඟා, ඉන්පසු ඉතිරි කොටස ගොඩනැඟීමට එම පුවරුවම භාවිතා කළා. එය වසා තැබූ pre-alpha එකක ඇත, එනම් මිතුරන් ටික දෙනෙකුට එය බොහෝ විට ක්‍රියා කරයි. මිල පිටුවක් නැහැ, පුවත්පතක් නැහැ, වර්ධන සැලැස්මක් නැහැ. එය ප්‍රයෝජනවත් යැයි හැඟේ නම්, තව ටිකක් විවෘත වූ විට උත්සාහ කිරීමට ඉල්ලා සිටිය හැක."]},{"n":144,"texts":["AI-gile යනු එක් මිනිසෙකුට සහ බොහෝ AI ඒජන්ට්වරුන්ට kanban පුවරුවකි. එය ඔබේම පරිගණකයේ ක්‍රියා කරන අතර සම්පූර්ණයෙන්ම නොමිලේ. ඔබ ව්‍යාපෘති එක් කරයි, හැම එකකටම ලීඩ් කෙනෙක් සහ කුඩා කණ්ඩායමක් ලැබේ. ඔබ ලීඩ් සමඟ Discord වගේ කතා කර අදහසක් විස්තර කරයි; ලීඩ් එය කාඩ්පත් සහ සැලැස්මක් බවට හරවා ඔබ යන්න ඔබනතුරු රැඳී සිටියි. කණ්ඩායම භාෂා ආකෘති සඳහා සාදන ලද සරල විධාන රේඛාවක් භාවිතා කර ප්‍රමුඛතා අනුපිළිවෙලට කාඩ්පත් වලින් වැඩ කරයි. කිසිවක් ඔබ වෙත ආපසු පැමිණීමට පෙර, AI පරීක්ෂකයා යෙදුමේ පිටපතක පියවර අනුගමනය කර තිරපිටපතක් අමුණයි. අවසන් වැඩ වෙනස් වූ ගොනු සහ වෙනස්කම් සමඟ ඔබේ ගොඩට පැමිණේ. ඔබ පිළිගනී, නැතහොත් අදහසක් තබයි, කණ්ඩායම අවදි වී නැවත උත්සාහ කරයි. කාඩ්පතක් අවසන් වෙත ගෙන යා හැක්කේ ඔබට පමණි. ගිණුම් නැහැ, ට්‍රැකර් නැහැ, cookies නැහැ.","AI-gile සමඟ දවසක්, ආසන්න වශයෙන්. සවසට ඔබ අදහස් කිහිපයක් තබයි: මේ බොත්තම වැරදි තැනක, ඒ ලැයිස්තුව පිළිවෙළට තිබිය යුතුයි, අඳුරු ප්‍රකාරයක් තිබිය හැකිද. ඔබ නිදාගනී. ඒජන්ට්වරු අදහස් කියවා, වෙනස්කම් කර, පරීක්ෂා කර ඔබට ආපසු දෙයි. කළ යුතු දේ අවසන් වුවහොත්, රාත්‍රී මුරකරු ඔබෙන් පිළිතුරක් අවශ්‍ය නොවන කාඩ්පත්වලින් එය backlog එකෙන් පුරවයි. උදේට කෙටි ගොඩක් ඇත: ප්‍රශ්න කිහිපයක් සහ පරීක්ෂා කළ යුතු දේ කිහිපයක්, හැම එකකම නිදිමත මිනිසෙකුට අනුගමනය කළ හැකි පියවර සහ ක්‍රියා කරන බව පෙන්වන තිරපිටපතක්. ඔබ ක්ලික් කර, හොඳ ඒවා පිළිගෙන, ඉතිරිය ආපසු යවයි. ටෝකන කවුන්ටරය ඒ සියල්ලට වැය වූ දේ පෙන්වයි, ටෝකන රහිත ප්‍රකාරය අඩු සති සඳහා ඇත. ඉන්පසු ඔබ උදේ ආහාරය ගනී, ඒජන්ට්වරුන්ට තවම ඒකට උදව් කළ නොහැක. ගිණුම් නැහැ, ට්‍රැකර් නැහැ, සියල්ල ඔබේ පරිගණකයේ.","මුලින්ම, AI-gile නොවන්නේ මොනවාද. එය startup එකක් නොවේ, විකිණීමට නොවේ, කිසිවෙක් ඔබේ දත්ත එකතු කරන්නේත් නැහැ. එය ඔබේ පරිගණකයේ ක්‍රියා කරන නොමිලේ පුවරුවකි, ගිණුම් නැහැ, ට්‍රැකර් නැහැ, cookies නැහැ. එය කුමක්ද: සියලු AI කේත ව්‍යාපෘති එකවර දැකිය හැකි පිළිවෙළට ඇති එකම තැනක්, කාඩ්පත් කරන ඒජන්ට් කණ්ඩායමක් සහ තීරණ ගන්නා ඔබ සමඟ. එය සම්බන්ධ කාඩ්පත් එකට ගලපයි, අවුල් සිරස්තල නිවැරදි කරයි, කේතය සැහැල්ලුවෙන් තබා ගැනීමට සොයා බලයි. එය ලන්දේසි සහ ෆ්ලෙමිශ් සිට මුහුදු කොල්ලකරුවන් සහ Klingon දක්වා භාෂා 120ක පමණ කතා කරයි. මිතුරන්ට පෞද්ගලිකව සහ සංකේතනය කර පණිවිඩ යැවිය හැක. එය ගොඩනැඟුවේ Rich සහ ඉවසිලිවන්ත ඒජන්ට්වරු රාශියක් විසින්, බොහෝ දුරට තමන්ම භාවිතා කරමිනි. එය වසා තැබූ pre-alpha එකක ඇති නිසා සමහර තැන්වල රළුයි. එය විනෝදජනක යැයි හැඟේ නම්, කාරුණිකව ඉල්ලන්න, ඔබට කලින් ඇතුළු විය හැක."]}],"quips":{"1":"එක වචනයක්. නිර්භීතයි. බොහෝ විට වැඩියි.","3":"වචන තුනක්. බොහෝ නිෂ්පාදන පිටුවලට වඩා දැන් ම අවංකයි.","8":"වචන අටක්. තවමත් stand-up එකකට වඩා කෙටියි.","21":"දිග කියන්නේ story points, ඔය අතරේ. ඔව්, ඇත්තෙන්ම.","55":"වචන පනස් පහක්. ඔබ කියවන අතරේ කාඩ්පත් දෙකක් අවසන් වුණා.","144":"ඒ දිගම එක. 233ක් නැහැ. ඒජන්ට්වරු නිදාගන්න ගියා."}},"timeline":{"first-idea.name":"පළමු අදහස","first-idea.line":"කේතයක් නොතිබුණු කාලයේ ඉතා පළමු සංවාදය.","first-board.name":"පළමු පුවරුව","first-board.line":"තමන්ගේම ගොඩනැගීම ලුහුබඳින පුවරුවක්: කාඩ්පත්, තීරු, ඇද දැමීම, ව්‍යාපෘති.","team-roles.name":"කණ්ඩායම සහ භූමිකා","team-roles.line":"ඒජන්ට් පැතිකඩ, කණ්ඩායම් සැකිලි, අවකාශ සහ කවුද කුමක් කරන්නේ.","install.name":"ස්ථාපනය සහ නිකුතු","install.line":"මිතුරෙකුට ස්ථාපනය කළ හැකි zip එකක්, ස්වයං යාවත්කාලීන, නාලිකා සහ ආපසු හැරවීම.","usage-saver.name":"භාවිතය ඉතිරි කරන්නා","usage-saver.line":"ධාවනවලට වැය වන දේ මැනගන්න, කේතය සැහැල්ලුවෙන් තබන්න, ඔබේ සීමාව ඉතිරි කරන්න.","friends.name":"මිතුරන් සහ බෙදාගැනීම","friends.line":"පෞද්ගලික පණිවිඩ, සංකේතිත රිලේ, ආරාධනා, භූමිකා සහ බෙදාගත් ව්‍යාපෘති.","languages.name":"භාෂා","languages.line":"හැම තිර පාඨයක්ම භාෂා ගොනුවක, ලන්දේසි සහ ෆ්ලෙමිශ් මුලින්.","ai-tester.name":"AI පරීක්ෂකයා","ai-tester.line":"පරීක්ෂකයෙක් හැම භාරදීමක්ම මුලින් පරීක්ෂා කර තමා දුටු දේ පෙන්වයි.","website.name":"වෙබ් අඩවිය","website.line":"aigile.lol, ටීසරය සහ මේ කාලරේඛාව.","streaming.name":"කතාබහ සහ ස්ට්‍රීමින්","streaming.line":"Discord, Twitch, OBS, ස්ට්‍රීමර් ප්‍රකාරය, GIF සහ ඉමෝජි.","no-ai.name":"AI රහිත සංස්කරණය","no-ai.line":"AI නොමැතිව කේත ලියන අයට පුවරුවක්, සහ පොදු පුවරු.","night-watch.name":"රාත්‍රී මුර","night-watch.line":"මුරකරුවෙක් සහ Scrum Master ඔබ නිදාගන්නා විට කණ්ඩායම් වැඩේ තබයි.","p-more.name":"අනිත් සියල්ල","p-more.line":"තමන්ගේ වාරය බලා සිටින කුඩා අදහස්.","p-android.name":"දුරකථනය සහ Android","p-android.line":"දුරකථනයකින් ඔබේ පුවරුවට ළඟා වන්න, ඉන්පසු Android යෙදුමක්.","p-release.name":"Alpha සහ ඉන් ඔබ්බට","p-release.line":"වසා තැබූ alpha, සජීවී අඩවිය, ඉන්පසු beta.","p-languages.name":"තවත් භාෂා","p-languages.line":"භාෂා සියයකට වැඩි, සහ ඉගෙනුම්කරුවන්ට ගැඹුරු ප්‍රකාරයක්.","p-engines.name":"තවත් AI එන්ජින්","p-engines.line":"හැම ඒජන්ට් කෙනෙකුටම Claude, Codex හෝ Gemini තෝරන්න.","p-pro.name":"වෘත්තීය භාවිතය","p-pro.line":"අවදානම් ලේබල්, ඒකාබද්ධ දොරටු, සිද්ධි කාඩ්පත් සහ ආරක්ෂක රේල්.","p-self.name":"ඔබ ගැන බලා ගැනීම","p-self.line":"මහන්සි ප්‍රකාරය, ස්වයං රැකවරණ මතක් කිරීම් සහ 4:20.","p-servers.name":"සේවාදායක සහ වර්ධනය","p-servers.line":"ගෝලීය සේවාදායක සැකසුම්, භූමිකා සහ වර්ධනය සඳහා සැලසුම් කිරීම.","p-livestream.name":"ස්ට්‍රීමින් අමතර","p-livestream.line":"Twitch කතාබහ, අභිරුචි ඉමෝජි සහ පොදු සජීවී දසුනක්."}};
